-- create "platform_sms_totals" table
CREATE TABLE "platform_sms_totals" ("id" uuid NOT NULL, "day" date NOT NULL, "count" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CONSTRAINT "platform_sms_totals_count_nonneg" CHECK (count >= 0));
-- create index "platform_sms_totals_day_key" to table: "platform_sms_totals"
CREATE UNIQUE INDEX "platform_sms_totals_day_key" ON "platform_sms_totals" ("day");
-- create "scheduler_leases" table
CREATE TABLE "scheduler_leases" ("id" uuid NOT NULL, "name" character varying NOT NULL, "holder" character varying NOT NULL, "expires_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "scheduler_leases_name_key" to table: "scheduler_leases"
CREATE UNIQUE INDEX "scheduler_leases_name_key" ON "scheduler_leases" ("name");
-- create "config_snapshots" table
CREATE TABLE "config_snapshots" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "hash" bytea NOT NULL, "doc" jsonb NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "config_snapshots_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT);
-- create index "configsnapshot_tenant_id_hash" to table: "config_snapshots"
CREATE UNIQUE INDEX "configsnapshot_tenant_id_hash" ON "config_snapshots" ("tenant_id", "hash");
-- create "dispatch_outbox" table
CREATE TABLE "dispatch_outbox" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "tenant_id" uuid NOT NULL, "notification_id" uuid NOT NULL, "run_id" uuid NOT NULL, "channel" character varying NOT NULL, "delay_s" bigint NOT NULL DEFAULT 0, "attempt" bigint NOT NULL DEFAULT 1, "traceparent" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "published_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "dispatch_outbox_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "dispatch_outbox_delay_range" CHECK ((delay_s >= 0) AND (delay_s <= 900)));
-- create index "dispatch_outbox_published" to table: "dispatch_outbox"
CREATE INDEX "dispatch_outbox_published" ON "dispatch_outbox" ("published_at") WHERE (published_at IS NOT NULL);
-- create index "dispatch_outbox_unpublished" to table: "dispatch_outbox"
CREATE INDEX "dispatch_outbox_unpublished" ON "dispatch_outbox" ("id") WHERE (published_at IS NULL);
-- create index "dispatchoutbox_tenant_id_notification_id" to table: "dispatch_outbox"
CREATE INDEX "dispatchoutbox_tenant_id_notification_id" ON "dispatch_outbox" ("tenant_id", "notification_id");
-- create "idempotency_records" table
CREATE TABLE "idempotency_records" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "key" character varying NOT NULL, "request_hash" bytea NOT NULL, "run_id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "idempotency_records_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT);
-- create index "idempotencyrecord_expires_at" to table: "idempotency_records"
CREATE INDEX "idempotencyrecord_expires_at" ON "idempotency_records" ("expires_at");
-- create index "idempotencyrecord_tenant_id_key" to table: "idempotency_records"
CREATE UNIQUE INDEX "idempotencyrecord_tenant_id_key" ON "idempotency_records" ("tenant_id", "key");
-- create "platform_sms_usage" table
CREATE TABLE "platform_sms_usage" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "day" date NOT NULL, "count" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"), CONSTRAINT "platform_sms_usage_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "platform_sms_usage_count_nonneg" CHECK (count >= 0));
-- create index "platformsmsusage_tenant_id_day" to table: "platform_sms_usage"
CREATE UNIQUE INDEX "platformsmsusage_tenant_id_day" ON "platform_sms_usage" ("tenant_id", "day");
-- create "runs" table
CREATE TABLE "runs" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "application_id" uuid NOT NULL, "environment_id" uuid NOT NULL, "workflow_id" uuid NOT NULL, "workflow_key" character varying NOT NULL, "snapshot_hash" bytea NOT NULL, "payload" bytea NULL, "context" jsonb NULL, "idempotency_key" character varying NULL, "source" character varying NOT NULL, "actor_type" character varying NOT NULL, "actor_id" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'accepted', "schedule_at" timestamptz NULL, "terminal_at" timestamptz NULL, "purged_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "runs_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT, CONSTRAINT "runs_snapshot_fk" FOREIGN KEY ("tenant_id", "snapshot_hash") REFERENCES "config_snapshots" ("tenant_id", "hash") ON UPDATE NO ACTION ON DELETE RESTRICT);
-- create index "run_tenant_id_application_id_environment_id_id" to table: "runs"
CREATE INDEX "run_tenant_id_application_id_environment_id_id" ON "runs" ("tenant_id", "application_id", "environment_id", "id");
-- create index "run_tenant_id_id" to table: "runs"
CREATE UNIQUE INDEX "run_tenant_id_id" ON "runs" ("tenant_id", "id");
-- create "scheduled_dispatch" table
CREATE TABLE "scheduled_dispatch" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "notification_id" uuid NOT NULL, "run_id" uuid NOT NULL, "channel" character varying NOT NULL, "due_at" timestamptz NOT NULL, "reason" character varying NOT NULL, "attempt" bigint NOT NULL DEFAULT 1, "traceparent" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "scheduled_dispatch_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT);
-- create index "scheduleddispatch_due_at" to table: "scheduled_dispatch"
CREATE INDEX "scheduleddispatch_due_at" ON "scheduled_dispatch" ("due_at");
-- create index "scheduleddispatch_tenant_id_notification_id" to table: "scheduled_dispatch"
CREATE INDEX "scheduleddispatch_tenant_id_notification_id" ON "scheduled_dispatch" ("tenant_id", "notification_id");
-- create "usage_records" table
CREATE TABLE "usage_records" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "notification_id" uuid NOT NULL, "channel" character varying NOT NULL, "credential_mode" character varying NOT NULL, "billing_basis" character varying NOT NULL, "country" character varying NOT NULL DEFAULT '', "billable_at" timestamptz NOT NULL, "unit_price_ref" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"), CONSTRAINT "usage_records_tenant_fk" FOREIGN KEY ("tenant_id") REFERENCES "tenants" ("id") ON UPDATE NO ACTION ON DELETE RESTRICT);
-- create index "usage_records_notification_id_key" to table: "usage_records"
CREATE UNIQUE INDEX "usage_records_notification_id_key" ON "usage_records" ("notification_id");
-- create index "usagerecord_tenant_id_billable_at" to table: "usage_records"
CREATE INDEX "usagerecord_tenant_id_billable_at" ON "usage_records" ("tenant_id", "billable_at");
